import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test
import your.package.functions.MethodInvokeTest_checkInjectedInvoker

class CallerSensitiveTest {

    @Test
    fun `verify injected invoker matches expected class`() {
        // ------------------------------------------------------------------
        // 1️⃣  Create / obtain the CSM instance that you want to inspect.
        //     In a real test this would be the instance returned by the
        //     caller‑sensitive method under test.
        // ------------------------------------------------------------------
        val csmInstance: CSM = createOrObtainCsm()   // <-- replace with your own logic

        // ------------------------------------------------------------------
        // 2️⃣  Call the helper.  The helper accepts a *JSON‑style* map where
        //     each value is the *string representation* of the Java object.
        //     The library will internally convert those strings back into
        //     the actual objects (via reflection or serialization).
        // ------------------------------------------------------------------
        val result = MethodInvokeTest_checkInjectedInvoker(
            mapOf(
                "csm" to csmInstance,
                "expected" to MyExpectedClass::class.java
            )
        )

        // ------------------------------------------------------------------
        // 3️⃣  Assert that the helper returned `true`.  If it returns `false`,
        //     the test will fail and you’ll get a helpful diagnostic message
        //     from the helper itself.
        // ------------------------------------------------------------------
        assertTrue(result, "The injected invoker was not found or did not match the expected class.")
    }

    // ----------------------------------------------------------------------
    // Helper that mimics whatever logic you normally use to create/obtain a
    // CSM instance.  Replace this with your own factory / builder / mock.
    // ----------------------------------------------------------------------
